# locate 3x3 squares
def find_squares(g):
    res={}
    for color in set(x for r in g for x in r if x):
        cells=[(i,j) for i,r in enumerate(g) for j,x in enumerate(r) if x==color]
        if len(cells)>=4:
            rs=[i for i,_ in cells];cs=[j for _,j in cells]
            res[color]=(min(rs),max(rs),min(cs),max(cs),len(cells))
    return res
