def f(g):
    import copy
    out=copy.deepcopy(g); H,W=len(g),len(g[0])
    rays={}
    blocks=[]
    for i in range(H-2):
        for j in range(W-2):
            v=g[i][j]
            if v and all(g[i+a][j+b]==v for a in range(3) for b in range(3)):
                blocks.append((i+1,j+1,v))
                rays.setdefault('r%d'%(i+1),set()).add(v)
                rays.setdefault('c%d'%(j+1),set()).add(v)
    for r,c,v in blocks:
        for jj in range(W): out[r][jj]=v
        for ii in range(H): out[ii][c]=v
    for i in range(H):
        for j in range(W):
            rs=rays.get('r%d'%i,set());cs=rays.get('c%d'%j,set())
            if rs and cs and rs!=cs and (i,j) not in [(r,c) for r,c,v in blocks]:
                out[i][j]=0
            elif rs and cs and rs!=cs:
                out[i][j]=g[i][j]
    return out
